const fake = [
  { id: 'demo-a', name: 'Harbor Studio', photos: ['Living', 'Kitchen'] },
  { id: 'demo-b', name: 'Garden Loft', photos: ['Kitchen', 'Bedroom', 'Terrace'] },
  { id: 'demo-c', name: 'Cedar House', photos: ['Living', 'Kitchen', 'Patio', 'Bedroom'] },
];
return fake.map(record => ({ json: record }));

const queue = $input.all().map(({json}) => ({ ...json, photoCount: json.photos.length }))
  .filter(x => x.id && x.photoCount > 0)
  .sort((a,b) => a.photoCount - b.photoCount || a.id.localeCompare(b.id));
return queue.map((item, index) => ({ json: { ...item, queuePosition: index + 1, status: 'READY' } }));
